/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field SalesTable.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailSalesTableSalesTable extends UPSPricingAttributeRetailSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, SalesTable);
}

public Set getAllowedValues()
{
    SalesTable salesTable;
    var        ret = new Set(Types::Int64);

    while select RecId from salesTable
    {
        ret.add(salesTable.RecId);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesTable, SalesTable));
    qbr.value(queryValue(_value));
}
